# --- Exact NFA for a star-glob: literal chunks joined by .* (dot = any char) ---
def build_nfa(pattern):
    chunks = pattern.split("*")
    # states: assign start/end char positions per chunk plus loop states
    trans = {}      # state -> list of (char_or_None, target); None = ANY
    eps = {}        # state -> list of targets
    def add_edge(d, s, lab, t):
        d.setdefault(s, []).append((lab, t))
    state = 0
    starts = []
    # chunk chain
    cur = 0
    alloc = [0]
    def new():
        alloc[0]+=1; return alloc[0]
    n = alloc[0]
    # build sequentially
    pos = new_start = 0
    prev_end = None
    # simpler linear construction:
    s = 0
    maxstate = 0
    trans={}; eps={}
    def ns():
        nonlocal maxstate
        maxstate+=1; return maxstate
    head = 0
    for i, ch in enumerate(chunks):
        if i > 0:
            loop = ns()
            eps.setdefault(head,[]).append(loop)
            trans.setdefault(loop,[]).append((None, loop))   # any char self-loop
            nxt = ns()
            eps.setdefault(loop,[]).append(nxt)
            head = nxt
        for c in ch:
            nxt = ns()
            trans.setdefault(head,[]).append((c, nxt))
            head = nxt
    accept = head
    return trans, eps, accept

def closure(eps, states):
    stack=list(states); seen=set(states)
    while stack:
        s=stack.pop()
        for t in eps.get(s,()):
            if t not in seen: seen.add(t); stack.append(t)
    return frozenset(seen)

def step(nfa, states, char):
    trans, eps, _ = nfa
    out=set()
    for s in states:
        for lab, t in trans.get(s,()):
            if lab is None or lab==char:
                out.add(t)
    return closure(eps, out)

def common_witness(p, q, alphabet="abx"):
    A, B = build_nfa(p), build_nfa(q)
    sa = closure(A[1], {0}); sb = closure(B[1], {0})
    start=(sa,sb)
    from collections import deque
    dq=deque([(sa,sb,"")]); seen={(sa,sb)}
