from accountability.authorization import intersection_pattern, _split_glob, _middle_runs_compatible, _merge_middle_runs

# Independent token-model oracle via brute force over token layouts.
# Existence: some sequence of fragment tokens (each occurrence taken from the
# union) in which run A and run B both embed as subsequences, using at most
# max(countA,countB) occurrences of each distinct fragment.
def oracle_compatible(A, B, cap=10):
    from functools import lru_cache
    frags = tuple(sorted(set(A) | set(B)))
    caps = {f: max(A.count(f), B.count(f)) for f in frags}
    @lru_cache(None)
    def go(i, j, used):
        if i == len(A) and j == len(B):
            return True
        # advance embedding A[i], B[j] by choosing a token from multiset
        for f in frags:
            k = dict(zip(frags, used)).get(f, 0)
            if k >= caps[f]:
                continue
        # Option 1: consume A[i] only
        if i < len(A):
            f = A[i]; k = dict(zip(frags, used)).get(f,0)
            if k < caps[f]:
                nu = tuple(v+1 if fr==f else v for fr,v in zip(frags,used))
                if go(i+1, j, nu): return True
        # Option 2: consume B[j] only
        if j < len(B):
            f = B[j]; k = dict(zip(frags, used)).get(f,0)
            if k < caps[f]:
                nu = tuple(v+1 if fr==f else v for fr,v in zip(frags,used))
                if go(i, j+1, nu): return True
        # Option 3: coincide
        if i < len(A) and j < len(B) and A[i] == B[j]:
            f = A[i]; k = dict(zip(frags, used)).get(f,0)
            if k < caps[f]:
                nu = tuple(v+1 if fr==f else v for fr,v in zip(frags,used))
                if go(i+1, j+1, nu): return True
        return False
    return go(0,0,tuple(0 for _ in frags))

def glob_re(p): return re.compile("^.*".join(re.escape(x) for x in p.split("*"))+"$", re.S)

def embeds(seq, sub):
    it = iter(seq); return all(any(x==s for x in it) for s in sub)

random.seed(123)
pool = ["a","b","x","ab","ba","aa",""]
def run():
    n = random.randint(0,5)
    return tuple(random.choice(pool) for _ in range(n))

bad_exist=bad_comm=bad_embed=bad_canon=bad_subset=0
exs=[]
for t in range(100000):
    A=run(); B=run()
    # full globs with star at both edges so only middles matter
    pa="*"+"*".join(A)+"*"; pb="*"+"*".join(B)+"*"
    ia=intersection_pattern(pa,pb); ib=intersection_pattern(pb,pa)
    want=oracle_compatible(tuple(f for f in A if f), tuple(f for f in B if f))
    got=ia is not None
    if got!=want:
        bad_exist+=1
        if len(exs)<15: exs.append(("EXIST",pa,pb,ia,want))
        continue
    if ia!=ib:
        bad_comm+=1
        if len(exs)<15: exs.append(("COMM",pa,pb,ia,ib))
    if got:
        _,mids,_=_split_glob(ia)
        mids=tuple(m for m in mids if m)
        # merged must embed both runs
        if not (embeds(mids,tuple(f for f in A if f)) and embeds(mids,tuple(f for f in B if f))):
            bad_embed+=1
            if len(exs)<15: exs.append(("EMBED",pa,pb,ia,mids))
        # occurrence counts of merged must equal max counts
        ca={}; cb={}
        for f in A: ca[f]=ca.get(f,0)+1
        for f in B: cb[f]=cb.get(f,0)+1
        cm={}
        for f in mids: cm[f]=cm.get(f,0)+1
        if any(cm.get(f,0)!=max(ca.get(f,0),cb.get(f,0)) for f in set(ca)|set(cb)):
            bad_canon+=1
            if len(exs)<15: exs.append(("COUNT",pa,pb,ia,mids))
        # glob subset: enumerate all strings len<=7 over ab and ensure match(ia)=>match(a)&match(b)
        for n in range(8):
            for tup in itertools.product("ab",repeat=n):
                s="".join(tup)
                if glob_re(ia).match(s) and not (glob_re(pa).match(s) and glob_re(pb).match(s)):
                    bad_subset+=1
                    if len(exs)<15: exs.append(("SUBSET",pa,pb,ia,s))
                    break
            else:
                continue
            break
print("bad_exist",bad_exist,"bad_comm",bad_comm,"bad_embed",bad_embed,"bad_count",bad_canon,"bad_subset",bad_subset)
for e in exs: print(e)
